<?php
namespace App\Http\Controllers\Web;
use App\Http\Controllers\Controller;use App\Models\ReconciliationRule;use Illuminate\Http\Request;
class ReconciliationRuleController extends Controller {
 public function index(){return view('reconciliation.rules.index',['rules'=>ReconciliationRule::query()->orderBy('priority')->get()]);}
 public function store(Request $r){$d=$r->validate(['name'=>'required|string|max:120','priority'=>'required|integer|min:1|max:9999','auto_approve_threshold'=>'required|numeric|min:50|max:100','amount_weight'=>'required|numeric|min:0|max:100','currency_weight'=>'required|numeric|min:0|max:100','date_weight'=>'required|numeric|min:0|max:100','reference_weight'=>'required|numeric|min:0|max:100','tax_id_weight'=>'required|numeric|min:0|max:100','absolute_tolerance'=>'required|numeric|min:0','percentage_tolerance'=>'required|numeric|min:0|max:100','date_days_full'=>'required|integer|min:0|max:365','date_days_partial'=>'required|integer|min:0|max:365']);$sum=$d['amount_weight']+$d['currency_weight']+$d['date_weight']+$d['reference_weight']+$d['tax_id_weight'];abort_unless(abs($sum-100)<.001,422,'Los pesos deben sumar 100.');ReconciliationRule::create(['name'=>$d['name'],'priority'=>$d['priority'],'rule_type'=>'weighted_scoring','auto_approve_threshold'=>$d['auto_approve_threshold'],'enabled'=>true,'config'=>['weights'=>['amount'=>$d['amount_weight'],'currency'=>$d['currency_weight'],'date'=>$d['date_weight'],'reference'=>$d['reference_weight'],'tax_id'=>$d['tax_id_weight']],'tolerances'=>['absolute'=>$d['absolute_tolerance'],'percentage'=>$d['percentage_tolerance'],'date_days_full'=>$d['date_days_full'],'date_days_partial'=>$d['date_days_partial']]]]);return back()->with('success','Regla creada correctamente.');}
 public function toggle(ReconciliationRule $rule){$rule->update(['enabled'=>!$rule->enabled]);return back()->with('success','Estado de la regla actualizado.');}
}
